import{_ as a,o as n,a as p,b as c}from"./app.C41L12d5.js";const l="/ascendc.github.io/assets/bank_struct.D7W6BNB_.png",t="/ascendc.github.io/assets/bank_bad.CiE57Jjk.png",e="/ascendc.github.io/assets/bank_good.BX0fff2x.png",h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMT算子性能优化","link":"/guide/operator_practice/simt_operator_optimization/simt_operator_optimization"},{"text":"内存访问","link":"/guide/operator_practice/simt_operator_optimization/memory_access/memory_access_merge"},{"text":"避免UB的Bank冲突","link":"/guide/operator_practice/simt_operator_optimization/memory_access/avoid_ub_bank_conflict_simt"}]},"headers":[],"relativePath":"guide/operator_practice/simt_operator_optimization/memory_access/avoid_ub_bank_conflict_simt.md","filePath":"guide/operator_practice/simt_operator_optimization/memory_access/avoid_ub_bank_conflict_simt.md","lastUpdated":1787050286000}'),i={name:"guide/operator_practice/simt_operator_optimization/memory_access/avoid_ub_bank_conflict_simt.md"};function o(_,s,r,d,w,b){return n(),p("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>避免UB的Bank冲突</h1><p>【优先级】高</p><p>【描述】SIMT编程模式下，一个Warp内的多个线程可能在同一条Unified Buffer（UB）访问指令中同时访问UB。对于使用UB中转做转置、重排等操作的算子，即使GM读写已经连续，仍需要分析UB访问模式，避免UB内部访问成为新的性能瓶颈。</p><div data-filter="950"><p>下图为UB bank结构示意图。Ascend 950PR/Ascend 950DT的UB划分为16个bank，并组织为8个bank group；SIMT编程模式下，每个bank进一步划分为4个subbank。若同一个Warp内多个线程在同一条UB访问指令中访问同一个bank group的相同编号subbank，硬件需要排队处理，从而形成subbank冲突并增加访问延迟。</p><p><strong>图 1</strong> bank结构示意图 <img src="'+l+`" alt="img" title="bank结构示意图"></p><p>SIMT编程方式下，bank冲突为更细粒度的subbank冲突，主要有以下两类：</p><ul><li><strong>写写冲突</strong>：多个写操作同时访问同一个bank group的相同编号subbank。</li><li><strong>读读冲突</strong>：多个读操作同时访问同一个bank group的相同编号subbank。</li></ul><p>详细的UB地址低位交织规则以及冲突场景可参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/03_simt_api/02_features/01_api_features/00_memory_access/bank_conflict">bank_conflict样例</a>。</p></div><div data-filter="950"><p>【样例介绍】以<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/03_simt_api/03_best_practices/00_memory_optimizations/matrix_transpose_practice">矩阵转置</a>为例，输入矩阵shape为1024×1024，数据类型为<code>float</code>。样例采用32×32的tile。当前基础配置中，Thread Block数量固定为硬件vector core数，每个Thread Block启动1024个线程，循环处理多个32×32 tile。全局访存合并版本先用UB暂存tile，使GM读写尽量保持连续；在此基础上，避免UB Bank冲突版本通过给UB tile增加padding，调整转置读阶段的UB行跨度，减少同一个Warp内线程集中访问相同subbank资源。</p><p>【反例】矩阵转置使用UB做中转，转置读阶段产生较严重bank冲突。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">TILE_DIM</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>

<span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">THREADS_PER_BLOCK</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">transpose_ub_kernel</span><span class="p">(</span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span>
<span class="w">                                                                         </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">width</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">height</span><span class="p">,</span>
<span class="w">                                                                         </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">total_tiles</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">tile</span><span class="p">[</span><span class="n">TILE_DIM</span><span class="p">][</span><span class="n">TILE_DIM</span><span class="p">];</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">tile_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span><span class="w"> </span><span class="n">tile_id</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">total_tiles</span><span class="p">;</span><span class="w"> </span><span class="n">tile_id</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">gridDim</span><span class="p">.</span><span class="n">x</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="p">...</span>
<span class="w">        </span><span class="n">tile</span><span class="p">[</span><span class="n">ty</span><span class="p">][</span><span class="n">tx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">x_index</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">y_index</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">width</span><span class="p">];</span>
<span class="w">        </span><span class="n">asc_syncthreads</span><span class="p">();</span>
<span class="w">        </span><span class="n">output</span><span class="p">[</span><span class="n">x_index</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">y_index</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">height</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tile</span><span class="p">[</span><span class="n">tx</span><span class="p">][</span><span class="n">ty</span><span class="p">];</span>
<span class="w">        </span><span class="n">asc_syncthreads</span><span class="p">();</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>上述实现通过UB中转保证了GM读写连续，这里的UB中的<code>tile</code>数组表示用于暂存32×32矩阵块的二维UB数组。<code>tile</code>数组的数据在UB中的排布为32×32。每行32个<code>float</code>，共128B，恰好跨越4个bank。转置写回时，同一个Warp的线程会读取UB中的一列元素，即访问<code>tile[tx][ty]</code>。由于行跨度固定为32个<code>float</code>，32个线程读取同一列时，访问地址会集中落到两个bank group的subbank 0，属于读读冲突场景。</p><p>下图展示了UB中的<code>tile</code>数组前12行元素按照行优先存储的排布，其中蓝色标记表示每行的第一个元素。按照地址低位交织规则，tile数组的第1行覆盖bank0到bank3，第2行覆盖bank4到bank7，第3行覆盖bank8到bank11，其余行依次类推。在32×32的UB tile中，同一个Warp的32个线程读取同一列时，会集中访问两个bank group的subbank 0。</p><img src="`+t+`"><p>在1024×1024矩阵转置样例中，该实现对应Case 5，性能数据如下：</p><table><thead><tr><th align="center">Task Duration(μs)</th><th align="center">aiv_time(μs)</th><th align="center">aiv_total_cycles</th><th align="center">aiv_vec_time(μs)</th><th align="center">aiv_vec_ratio</th><th align="center">aiv_scalar_time(μs)</th><th align="center">aiv_scalar_ratio</th></tr></thead><tbody><tr><td align="center">23.912</td><td align="center">22.745</td><td align="center">37528.9</td><td align="center">22.297</td><td align="center">0.980</td><td align="center">0.435</td><td align="center">0.019</td></tr></tbody></table><p>【正例】为UB tile增加padding，打散列方向访问的bank分布。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">TILE_DIM</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">TILE_PAD</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">TILE_PAD_STRIDE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">TILE_DIM</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">TILE_PAD</span><span class="p">;</span>

<span class="n">__global__</span><span class="w"> </span><span class="nf">__launch_bounds__</span><span class="p">(</span><span class="n">THREADS_PER_BLOCK</span><span class="p">)</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">transpose_ub_pad_kernel</span><span class="p">(</span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">,</span>
<span class="w">                                                                             </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">width</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">height</span><span class="p">,</span>
<span class="w">                                                                             </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">total_tiles</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">tile</span><span class="p">[</span><span class="n">TILE_DIM</span><span class="p">][</span><span class="n">TILE_PAD_STRIDE</span><span class="p">];</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">tile_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">blockIdx</span><span class="p">.</span><span class="n">x</span><span class="p">;</span><span class="w"> </span><span class="n">tile_id</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">total_tiles</span><span class="p">;</span><span class="w"> </span><span class="n">tile_id</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="n">gridDim</span><span class="p">.</span><span class="n">x</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="p">...</span>
<span class="w">        </span><span class="n">tile</span><span class="p">[</span><span class="n">ty</span><span class="p">][</span><span class="n">tx</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">input</span><span class="p">[</span><span class="n">x_index</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">y_index</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">width</span><span class="p">];</span>
<span class="w">        </span><span class="n">asc_syncthreads</span><span class="p">();</span>
<span class="w">        </span><span class="n">output</span><span class="p">[</span><span class="n">x_index</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">y_index</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">height</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tile</span><span class="p">[</span><span class="n">tx</span><span class="p">][</span><span class="n">ty</span><span class="p">];</span>
<span class="w">        </span><span class="n">asc_syncthreads</span><span class="p">();</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div><p>上述实现将UB中的<code>tile</code>数组从32×32调整为32×34，仅改变UB中每行的物理跨度。增加2列padding后，每行包含34个<code>float</code>数据，行跨度变为17个subbank，同一列元素会错开排布到不同的subbank。下图为增加padding后的内存布局；从地址映射看，同一个Warp的32个线程的UB访问会分布到各个bank group的不同subbank中，即同一条访问指令下每个subbank仅有一个线程访问，从而避免上述读读冲突。</p><img src="`+e+'"><p>在1024×1024矩阵转置样例中，该实现对应Case 6，性能数据如下：</p><table><thead><tr><th align="center">Task Duration(μs)</th><th align="center">aiv_time(μs)</th><th align="center">aiv_total_cycles</th><th align="center">aiv_vec_time(μs)</th><th align="center">aiv_vec_ratio</th><th align="center">aiv_scalar_time(μs)</th><th align="center">aiv_scalar_ratio</th></tr></thead><tbody><tr><td align="center">15.152</td><td align="center">13.641</td><td align="center">22507.6</td><td align="center">13.176</td><td align="center">0.966</td><td align="center">0.453</td><td align="center">0.033</td></tr></tbody></table><p>从Task Duration看，增加padding后的执行耗时为15.152μs，相比未加padding的UB中转版本23.912μs，下降约36.6%。这说明在GM读写已经连续的前提下，UB内部的bank冲突仍会影响算子端到端耗时；通过将UB tile从32×32调整为32×34，列方向访问被分散到各个bank group的不同subbank上，避免了上述读读冲突，因此算子的整体运行时间进一步下降。</p></div><p>【总结】当SIMT算子已经通过UB中转解决GM非连续访问后，应继续分析UB访问是否会产生bank冲突。若同一个Warp沿列方向访问二维UB数组，且行跨度容易让访问集中到相同bank资源，可以通过增加padding、调整行跨度或重新排布数据来避免bank冲突。</p></article></div>',1)])])}const g=a(i,[["render",o]]);export{h as __pageData,g as default};
